    // ASCII-only fallback mark for terminals too narrow for the full art.
    const std::vector<std::string>& VampireCompact() {
        static const std::vector<std::string> kArt = {
            R"(   /\             /\   )",
            R"(  /  \___________/  \  )",
            R"( |   .-'       '-.   | )",
            R"( |  (  o       o  )  | )",
            R"(  \  \    ___    /  /  )",
            R"(   \  '..' V '..'  /   )",
            R"(    '--.._____..--'    )",
        };
        return kArt;
    }

    // Two rows only: used when the terminal is too short for the full artwork.
    const std::vector<std::string>& VampireMini() {
        static const std::vector<std::string> kArt = {
            R"( /\-----/\ )",
            R"(( o  V  o ))",
        };
        return kArt;
    }

    size_t MaxWidth(const std::vector<std::string>& art) {
        size_t w = 0;
        for (const auto& row : art) {
            w = std::max(w, Text::VisibleWidth(row));
        }
        return w;
    }

